select c.org_id, c.job_id, c.id, 'review_item.failed', 'import', '2025-11-25'::timestamptz, '{"department":"Utilities (Permits)","round":1,"status":"Requires Re-submit"}'::jsonb, 'energov:review_item:0f287868-7991-4c16-a7e0-db41db5ce36d:Requires Re-submit'
from ops.permit_cases c where c.id = (select id from ops.permit_cases where org_id = (select id from _org) and portal = 'energov:marion' and number = '2025102955') on conflict (org_id, dedupe_key) do nothing;
commit;
